    vertical-align: top !important;
}
</style>

<table style="width: 100%; border-collapse: collapse;">
  <tr>
    <td style="width: 60%; font-size: 14px; font-weight: bold;">
      {{ _("Invoice") }} {{ doc.name }}
    </td>
    <td style="width: 40%; font-size: 12px;">
      <div>{{ _("Invoice date") }}: {{ doc.posting_date or '' }}</div>
      <div>{{ _("Expiration date") }}: {{ doc.due_date or '' }}</div>
    </td>
  </tr>
</table>

<table class="compact-info" style="width: 100%; border-collapse: collapse; font-size: 12px;">
  <tr>
    <td style="width: 60%;">
      <strong>{{ _("Reference") }}:</strong> {{ doc.reference or '' }}
    </td>
    <td style="width: 40%;">
      <strong>{{ _("Licence plate") }}:</strong> {{ doc.licence_plate or '' }}
    </td>
  </tr>
  <tr>
    <td>
      <strong>{{ _("Description") }}:</strong> {{ doc.description_title or '' }}
    </td>
    <td>
      <strong>{{ _("Mileage") }}:</strong> {{ doc.mileage + ' km' if doc.mileage else '' }}
    </td>
  </tr>
</table>
